Section CANSEC1. Context {rc : runConstT}.

Lemma sqd_i5_ok : forall P OEND LLO LEND LOCV, sqd_static P OEND LLO LEND LOCV -> zd_initfse_stmtA ->
  (w_LLT P + 4104 < 2^47 /\ w_OFT P + 2056 < 2^47 /\ w_MLT P + 4104 < 2^47) ->
  ai_I7 P OEND LLO LEND LOCV -> ai_I5 P OEND LLO LEND LOCV.
Proof.
  intros P OEND LLO LEND LOCV ST IFS TST CONT.
  destruct P as [ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LITSZ LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1].
  cbv delta [ai_I5 sqd_iregs sqd_ifrN sqd_ifrI sqd_imidC sqd_ic176C sqd_iffD]. cbn [app w_ra w_gp w_tp w_s0 w_s1 w_s2 w_s3 w_s4 w_s5 w_s6 w_s7 w_s8 w_s9 w_s10 w_s11 w_F w_fc w_m w_SPV w_lo w_DCTX w_DST w_CAP w_B0 w_B1 w_SEQ w_nbSeq w_LLT w_MLT w_OFT w_PFX w_LITP w_LITSZ w_LITB w_LOC w_sq w_tLL w_tOF w_tML w_huf w_r0 w_r1 w_r2 w_pde w_dend w_expd w_pcs w_dsz w_bt w_stg w_le w_fe w_ws w_AI w_fflag w_L w_RNG w_st w_LB w_m0 w_FRB w_FF w_SHF w_D8 w_j0 w_j224 w_jfh w_j144 w_jsh0 w_jsh1].
  intros m1 jb j48 jc144 jc168 jd jseq jpad j104 p0 p1 p2 cw A0 bc ptr sLL sOF x5 x6 x7 x13 x14 x15 x16 x17 x27 x28 x29 x30 x31 INV EA0 HBC BOK HS1 HS2.
  subst A0.
  cbv delta [ai_I7 sqd_iregs sqd_ifrN sqd_ifrI sqd_imidC sqd_ic176C sqd_ffr] in CONT. cbn [app w_ra w_gp w_tp w_s0 w_s1 w_s2 w_s3 w_s4 w_s5 w_s6 w_s7 w_s8 w_s9 w_s10 w_s11 w_F w_fc w_m w_SPV w_lo w_DCTX w_DST w_CAP w_B0 w_B1 w_SEQ w_nbSeq w_LLT w_MLT w_OFT w_PFX w_LITP w_LITSZ w_LITB w_LOC w_sq w_tLL w_tOF w_tML w_huf w_r0 w_r1 w_r2 w_pde w_dend w_expd w_pcs w_dsz w_bt w_stg w_le w_fe w_ws w_AI w_fflag w_L w_RNG w_st w_LB w_m0 w_FRB w_FF w_SHF w_D8 w_j0 w_j224 w_jfh w_j144 w_jsh0 w_jsh1] in CONT.
  (* [comment removed for export] *)
  pose proof INV as (FR0 & FRF0 & IREST).
  destruct (sqd_cb16_words m1 FF [CB 32 jfh; C8 cw; C4 (Z_to_bv 64 bc); CB 4 jpad; C8 (Z_to_bv 64 ptr); C8 (Z_to_bv 64 SEQ); C8 (Z_to_bv 64 (SEQ + 8)); C8 (Z_to_bv 64 sLL); C8 (Z_to_bv 64 (LLT + 8)); C8 (Z_to_bv 64 sOF); C8 (Z_to_bv 64 (OFT + 8))] j104 [C8 p0; C8 p1; C8 p2; CB 104 j144; C8 (Z_to_bv 64 (fflag L 2 FF))] FRF0) as (u1 & u2 & FRF1).
  cbn [app] in FRF1.
  assert (INV1 : sqd_iinv (mkSQP ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LITSZ LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1) OEND LLO LEND LOCV m1 _ _) by (exact (conj FR0 (conj FRF1 IREST))).
  clear INV FR0 FRF0 FRF1 IREST.
  (* [comment removed for export] *)
  eapply evtF_cut.
  { eapply (sqd_initfse_ispec (mkSQP ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LITSZ LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1) OEND LLO LEND LOCV m1 _ cw bc jpad ptr [C8 (Z_to_bv 64 sLL); C8 (Z_to_bv 64 (LLT + 8)); C8 (Z_to_bv 64 sOF); C8 (Z_to_bv 64 (OFT + 8))] u1 u2 [C8 p0; C8 p1; C8 p2; CB 104 j144; C8 (Z_to_bv 64 (fflag L 2 FF))] MLT tML K_ML 82 (FF + 104) (DCTX + 26692) (2147450880 + D8 + 3336));
      [ exact ST | exact IFS | exact INV1 | cbn [w_LLT w_OFT w_MLT w_tLL w_tOF w_tML]; right; right; split; [reflexivity | split; reflexivity] | exact TST
      | cbn [cells_size csize Nat.add length w_FF]; clear; lia | cbn [cells_size csize Nat.add length]; clear; lia | cbn [cells_size csize Nat.add length]; clear; lia
      | clear - HBC; lia | clear; lia | exact BOK ]. }
  clear INV1. cbv delta [sqd_initfse_ipost sqd_iregs]. cbn [w_ra w_gp w_tp w_s0 w_s1 w_s2 w_s3 w_s4 w_s5 w_s6 w_s7 w_s8 w_s9 w_s10 w_s11 w_F w_fc w_m w_SPV w_lo w_DCTX w_DST w_CAP w_B0 w_B1 w_SEQ w_nbSeq w_LLT w_MLT w_OFT w_PFX w_LITP w_LITSZ w_LITB w_LOC w_sq w_tLL w_tOF w_tML w_huf w_r0 w_r1 w_r2 w_pde w_dend w_expd w_pcs w_dsz w_bt w_stg w_le w_fe w_ws w_AI w_fflag w_L w_RNG w_st w_LB w_m0 w_FRB w_FF w_SHF w_D8 w_j0 w_j224 w_jfh w_j144 w_jsh0 w_jsh1].
  intros ms2 (m2 & cw2 & bc2 & jpad2 & ptr2 & sv & t0_ & t1_ & t2_ & a0_ & a1_ & a2_ & a3_ & a4_ & a5_ & a6_ & a7_ & t3_ & t4_ & t5_ & t6_ & -> & INV2 & HST & HBC2 & BOK2).
  replace (ret_pc (Z_to_bv 64 606596)) with (Z_to_bv 64 606596) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]).
  cbv delta [sbd_cells] in INV2. cbn [app] in INV2.
  (* [comment removed for export] *)
  eapply CONT; [exact INV2 | clear - HBC2; lia | exact BOK2 | exact HS1 | exact HS2 | exact HST].
Qed.

End CANSEC1.
